'use strict';
/*
 * GENERATED by tools/make_looks.py from tools/looks_src/engine_template.js + looks.json.
 * Edit those two files, not this one.
 *
 * VOL PPT layout pack. Contract: module.exports = { LAYOUTS, resolveTheme, buildDeck }.
 * Canvas: 10 x 5.625 in. Only pptxgenjs + fs + path are used. No network.
 */
const PptxGenJS = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const LOOK = __LOOK__;
const THEMES = LOOK.themes;
const DEFAULT_THEME = LOOK.defaultTheme;

// ---------- small helpers ----------
function bl(list, max) {
  return (list || []).slice(0, max || 8).map((t) => ({ text: String(t), options: { bullet: { indent: 14 }, breakLine: true } }));
}
function plain(list, max) {
  return (list || []).slice(0, max || 4).map(String).join('\n');
}
function txt(s, text, o) {
  s.addText(text, Object.assign({ margin: 0, fit: 'shrink', shrinkText: true }, o));
}
function rect(s, X, Y, W, H, color, extra) {
  s.addShape('rect', Object.assign({ x: X, y: Y, w: W, h: H, fill: { color: color }, line: { color: color } }, extra || {}));
}
// A photo, or a calm placeholder block when the slide has no photo.
function photo(s, x, X, Y, W, H) {
  if (x.img) {
    s.addImage({ path: x.img, x: X, y: Y, w: W, h: H, sizing: { type: 'cover', w: W, h: H } });
  } else {
    rect(s, X, Y, W, H, x.C.soft);
    rect(s, X + W / 2 - 0.4, Y + H / 2 - 0.03, 0.8, 0.06, x.C.accent);
  }
}

// ---------- layout archetypes (each returns flags: { bleed } when a photo touches the edges) ----------
const ARCH = {
  titleLeft(s, x) {
    txt(s, x.title, { x: 0.9, y: 1.2, w: 8.2, h: 1.9, fontFace: x.FH, fontSize: 38, bold: true, color: x.C.ink, valign: 'bottom' });
    rect(s, 0.9, 3.3, 1.4, 0.06, x.C.accent);
    if (x.bullets.length) txt(s, bl(x.bullets, 3), { x: 0.9, y: 3.55, w: 8.2, h: 1.3, fontFace: x.FB, fontSize: 16, color: x.C.muted, valign: 'top' });
    return {};
  },
  photoRight(s, x) {
    txt(s, x.title, { x: 0.6, y: 0.6, w: 4.6, h: 1.2, fontFace: x.FH, fontSize: 26, bold: true, color: x.C.ink, valign: 'top' });
    txt(s, bl(x.bullets, 9), { x: 0.6, y: 1.95, w: 4.6, h: 3.2, fontFace: x.FB, fontSize: 15, color: x.C.ink, valign: 'top', paraSpaceAfter: 6 });
    photo(s, x, 5.5, 0, 4.5, 5.625);
    return { bleed: true };
  },
  photoLeft(s, x) {
    photo(s, x, 0, 0, 4.5, 5.625);
    txt(s, x.title, { x: 5.0, y: 0.6, w: 4.4, h: 1.2, fontFace: x.FH, fontSize: 26, bold: true, color: x.C.ink, valign: 'top' });
    txt(s, bl(x.bullets, 9), { x: 5.0, y: 1.95, w: 4.4, h: 3.2, fontFace: x.FB, fontSize: 15, color: x.C.ink, valign: 'top', paraSpaceAfter: 6 });
    return { bleed: true };
  },
  statement(s, x) {
    txt(s, x.title, { x: 1.0, y: 1.1, w: 8.0, h: 2.1, fontFace: x.FH, fontSize: 36, bold: true, color: x.C.ink, align: 'center', valign: 'bottom' });
    rect(s, 4.4, 3.4, 1.2, 0.05, x.C.accent);
    if (x.bullets.length) txt(s, plain(x.bullets, 4), { x: 1.5, y: 3.65, w: 7.0, h: 1.3, fontFace: x.FB, fontSize: 15, color: x.C.muted, align: 'center', valign: 'top' });
    return {};
  },
  chapter(s, x) {
    txt(s, String(x.num).padStart(2, '0'), { x: 0.9, y: 0.9, w: 4.0, h: 2.0, fontFace: x.FH, fontSize: 96, bold: true, color: x.C.accent, valign: 'middle' });
    txt(s, x.title, { x: 0.9, y: 3.0, w: 8.2, h: 1.6, fontFace: x.FH, fontSize: 34, bold: true, color: x.C.ink, valign: 'top' });
    return {};
  },
  cards(s, x) {
    txt(s, x.title, { x: 0.6, y: 0.5, w: 8.8, h: 0.9, fontFace: x.FH, fontSize: 26, bold: true, color: x.C.ink, valign: 'top' });
    const n = Math.min(6, x.bullets.length);
    for (let i = 0; i < n; i++) {
      const cx = 0.6 + (i % 3) * 3.0;
      const cy = 1.7 + Math.floor(i / 3) * 1.75;
      rect(s, cx, cy, 2.8, 1.55, x.C.soft);
      rect(s, cx, cy, 2.8, 0.06, x.C.accent);
      txt(s, x.bullets[i], { x: cx + 0.15, y: cy + 0.22, w: 2.5, h: 1.2, fontFace: x.FB, fontSize: 13, color: x.C.ink, valign: 'top' });
    }
    return {};
  },
  backdrop(s, x) {
    photo(s, x, 0, 0, 10, 5.625);
    rect(s, 0.6, 2.5, 6.2, 2.5, x.C.bg, { fill: { color: x.C.bg, transparency: 6 }, line: { color: x.C.accent, width: 1 } });
    txt(s, x.title, { x: 0.9, y: 2.65, w: 5.6, h: 0.9, fontFace: x.FH, fontSize: 24, bold: true, color: x.C.ink, valign: 'top' });
    txt(s, bl(x.bullets, 4), { x: 0.9, y: 3.6, w: 5.6, h: 1.3, fontFace: x.FB, fontSize: 14, color: x.C.ink, valign: 'top' });
    return { bleed: true };
  },
  twoCol(s, x) {
    txt(s, x.title, { x: 0.6, y: 0.5, w: 8.8, h: 0.9, fontFace: x.FH, fontSize: 26, bold: true, color: x.C.ink, valign: 'top' });
    const all = x.bullets.slice(0, 10);
    const half = Math.ceil(all.length / 2);
    txt(s, bl(all.slice(0, half), 5), { x: 0.6, y: 1.7, w: 4.2, h: 3.2, fontFace: x.FB, fontSize: 15, color: x.C.ink, valign: 'top', paraSpaceAfter: 6 });
    if (all.length > half) txt(s, bl(all.slice(half), 5), { x: 5.2, y: 1.7, w: 4.2, h: 3.2, fontFace: x.FB, fontSize: 15, color: x.C.ink, valign: 'top', paraSpaceAfter: 6 });
    return {};
  },
  closing(s, x) {
    txt(s, x.title, { x: 1.0, y: 1.5, w: 8.0, h: 1.7, fontFace: x.FH, fontSize: 42, bold: true, color: x.C.ink, align: 'center', valign: 'bottom' });
    rect(s, 4.4, 3.4, 1.2, 0.05, x.C.accent);
    if (x.bullets.length) txt(s, plain(x.bullets, 2), { x: 1.5, y: 3.65, w: 7.0, h: 1.0, fontFace: x.FB, fontSize: 16, color: x.C.muted, align: 'center', valign: 'top' });
    return {};
  },
};

// Shared edge decoration + slide number (kept off full-bleed photo layouts).
function chrome(s, x, fl) {
  if (fl.bleed) return;
  const D = LOOK.deco;
  const a = x.C.accent;
  if (D.bar === 'top') rect(s, 0, 0, 10, 0.12, a);
  if (D.bar === 'left') rect(s, 0, 0, 0.14, 5.625, a);
  if (D.frame) s.addShape('rect', { x: 0.2, y: 0.2, w: 9.6, h: 5.225, fill: { color: x.C.bg, transparency: 100 }, line: { color: a, width: 0.75, transparency: 55 } });
  if (D.footer !== 'none' && x.type !== 'title') {
    txt(s, x.num + ' / ' + x.total, { x: 8.2, y: 5.0, w: 1.3, h: 0.3, fontFace: x.FB, fontSize: 10, color: x.C.muted, align: 'right' });
  }
}

// Layouts with limited room hand over to the two-column layout when a slide
// has more bullets than fit, so no bullet is ever silently dropped. (A chapter
// slide normally has no bullets; it only hands over on a content slide.)
const ROOM = { cards: 6, backdrop: 4, titleLeft: 3, statement: 4, closing: 2, chapter: 0 };

function pickKey(key, x) {
  const room = ROOM[key];
  if (room === undefined || x.bullets.length <= room) return key;
  if (room === 0 && x.type !== 'content' && x.type !== 'recap') return key;
  return 'twoCol';
}

const LAYOUTS = LOOK.layouts.map(function (pair) {
  return {
    name: pair[0],
    build(s, x) {
      const fl = ARCH[pickKey(pair[1], x)](s, x) || {};
      chrome(s, x, fl);
    },
  };
});

// Never throws: an unknown id falls back to the default theme.
function resolveTheme(themeId, fontOverride) {
  const t = THEMES[themeId] || THEMES[DEFAULT_THEME];
  const over = fontOverride && fontOverride !== 'default' ? fontOverride : null;
  return { C: Object.assign({}, t.colors), FH: over || t.fh, FB: over || t.fb };
}

function buildDeck(slides, images, opts) {
  opts = opts || {};
  const th = opts.C ? { C: opts.C, FH: opts.FH, FB: opts.FB } : resolveTheme(DEFAULT_THEME);
  const pres = new PptxGenJS();
  pres.layout = 'LAYOUT_16x9';
  pres.title = opts.deckTitle || LOOK.name;
  let rot = 0;
  (slides || []).forEach(function (sl, i) {
    const s = pres.addSlide();
    s.background = { color: th.C.bg };
    let idx;
    if (opts.mode === 'single') {
      idx = Math.min(Math.max(opts.layoutNum || 1, 1), LAYOUTS.length) - 1;
    } else if (LOOK.types[sl.type] !== undefined) {
      idx = LOOK.types[sl.type];
    } else {
      idx = LOOK.content[rot % LOOK.content.length];
      rot++;
    }
    const img = images && images[String(i + 1)];
    LAYOUTS[idx].build(s, {
      C: th.C, FH: th.FH, FB: th.FB,
      title: String(sl.title || ''),
      bullets: (sl.bullets || []).map(String),
      img: img && fs.existsSync(img) ? img : null,
      num: i + 1, total: slides.length, type: sl.type,
    });
  });
  return pres;
}

module.exports = { LAYOUTS, resolveTheme, buildDeck };

// Command line, for testing a pack on its own:
//   node engine.js <outline.md> <imagesDir> <out.pptx> [--layout=N|mix] [--theme=id]
if (require.main === module) {
  const args = process.argv.slice(2).filter((a) => !a.startsWith('--'));
  const flags = process.argv.slice(2).filter((a) => a.startsWith('--'));
  const [outlinePath, imagesDir, outPath] = args;
  if (!outlinePath || !imagesDir || !outPath) {
    console.error('Usage: node engine.js <outline.md> <imagesDir> <out.pptx> [--layout=N|mix] [--theme=id]');
    process.exit(2);
  }
  const flag = (k) => { const f = flags.find((a) => a.startsWith('--' + k + '=')); return f ? f.split('=')[1] : null; };
  const layoutFlag = flag('layout') || 'mix';
  const lines = fs.readFileSync(outlinePath, 'utf8').split(/\r?\n/);
  const slides = [];
  lines.forEach(function (ln) {
    const m = /^##\s+(.*)$/.exec(ln);
    if (m) {
      let title = m[1].trim();
      let type = slides.length === 0 ? 'title' : 'content';
      if (title.charAt(0) === '★') { type = 'chapter'; title = title.slice(1).trim(); }
      slides.push({ title: title, type: type, bullets: [] });
    } else if (/^\s*-\s+/.test(ln) && slides.length) {
      slides[slides.length - 1].bullets.push(ln.replace(/^\s*-\s+/, '').trim());
    }
  });
  if (slides.length > 3) slides[slides.length - 1].type = 'closing';
  const images = {};
  if (fs.existsSync(imagesDir)) {
    fs.readdirSync(imagesDir).forEach(function (f) {
      const m = /^(\d+)\b.*\.(png|jpe?g)$/i.exec(f);
      if (m) images[String(parseInt(m[1], 10))] = path.resolve(imagesDir, f);
    });
  }
  const th = resolveTheme(flag('theme'));
  const pres = buildDeck(slides, images, {
    C: th.C, FH: th.FH, FB: th.FB,
    mode: layoutFlag === 'mix' ? 'mix' : 'single',
    layoutNum: layoutFlag === 'mix' ? 1 : parseInt(layoutFlag, 10),
    deckTitle: 'Sample',
  });
  pres.writeFile({ fileName: outPath }).then(function () { console.log('Wrote ' + outPath); });
}
